import { cn } from '@/lib/utils/cn';
import type { LengthMode } from '@/types/knowledge.types';
import { useLanguage } from '@/components/layout/LanguageProvider';

interface Props {
  value: LengthMode;
  onChange: (v: LengthMode) => void;
}

const OPTIONS: LengthMode[] = ['compact', 'standard', 'comprehensive'];

export function LengthModeSlider({ value, onChange }: Props) {
  const { t } = useLanguage();
  return (
    <div>
      <p className="mb-3 text-sm font-bold text-text-primary">{t('wizard.settings.lengthMode')}</p>
      <div className="grid grid-cols-3 gap-2">
        {OPTIONS.map((option) => (
          <button
            key={option}
            type="button"
            onClick={() => onChange(option)}
            className={cn(
              'rounded-lg border p-3 text-center transition-all',
              value === option
                ? 'border-primary bg-primary/10 text-primary'
                : 'border-border bg-surface text-text-secondary hover:border-primary/50',
            )}
          >
            <p className="text-sm font-bold">{t(`wizard.settings.${option}`)}</p>
            <p className="mt-0.5 text-xs opacity-70">{t(`wizard.settings.${option}Sub`)}</p>
          </button>
        ))}
      </div>
    </div>
  );
}