import { Check } from 'lucide-react';
import { cn } from '@/lib/utils/cn';

interface Props {
  label: string;
  description?: string;
  icon?: string;
  selected: boolean;
  onSelect: () => void;
}

export function ChoiceCard({ label, description, icon, selected, onSelect }: Props) {
  return (
    <button
      type="button"
      onClick={onSelect}
      className={cn(
        'group relative w-full rounded-xl border p-4 text-start transition-all',
        selected
          ? 'border-primary bg-primary/10 shadow-[0_0_20px_rgba(139,92,246,0.2)]'
          : 'border-border bg-surface hover:border-primary/50 hover:bg-surface-elevated',
      )}
    >
      {selected && (
        <div className="absolute end-3 top-3 flex h-6 w-6 items-center justify-center rounded-full bg-primary">
          <Check size={14} className="text-white" />
        </div>
      )}
      <div className="flex items-start gap-3">
        {icon && <span className="text-2xl">{icon}</span>}
        <div className="flex-1">
          <p className="font-bold text-text-primary">{label}</p>
          {description && (
            <p className="mt-1 text-xs text-text-secondary">{description}</p>
          )}
        </div>
      </div>
    </button>
  );
}