import { cn } from '@/lib/utils/cn';
import type { PromptFormat } from '@/types/wizard.types';
import { useLanguage } from '@/components/layout/LanguageProvider';

interface Props {
  value: PromptFormat;
  onChange: (v: PromptFormat) => void;
}

export function ChainingToggle({ value, onChange }: Props) {
  const { t } = useLanguage();
  return (
    <div>
      <p className="mb-2 text-sm font-bold text-text-primary">{t('wizard.settings.promptFormat')}</p>
      <div className="flex gap-2">
        <button
          type="button"
          onClick={() => onChange('single')}
          className={cn(
            'flex-1 rounded-lg border p-3 text-center text-sm font-bold transition-all',
            value === 'single'
              ? 'border-primary bg-primary/10 text-primary'
              : 'border-border bg-surface text-text-secondary hover:border-primary/50',
          )}
        >
          {t('wizard.settings.singlePrompt')}
        </button>
        <button
          type="button"
          onClick={() => onChange('chained')}
          className={cn(
            'flex-1 rounded-lg border p-3 text-center text-sm font-bold transition-all',
            value === 'chained'
              ? 'border-primary bg-primary/10 text-primary'
              : 'border-border bg-surface text-text-secondary hover:border-primary/50',
          )}
        >
          {t('wizard.settings.chainedPrompts')}
        </button>
      </div>
    </div>
  );
}